-- 078: 经费控制增强
-- 发票人工录入查重、预算调整版本、年度结算/封账和付款回写约束。
-- 本迁移只登记脚本，不在开发任务中执行；部署时由 apply-postgres-migrations.sh 按序执行。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研经费发票" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "报销编号" integer,
    "发票号码" varchar(100) NOT NULL,
    "发票代码" varchar(50),
    "开票日期" date,
    "金额" numeric(18,2) NOT NULL,
    "供应商名称" varchar(300) NOT NULL,
    "供应商税号" varchar(100),
    "发票类型" varchar(30) NOT NULL DEFAULT '电子普通发票',
    "查重状态" varchar(20) NOT NULL DEFAULT '未查重',
    "重复说明" varchar(1000),
    "附件路径" text,
    "OCR状态" varchar(20) NOT NULL DEFAULT '未接入',
    "复核人编号" integer,
    "复核时间" timestamp without time zone,
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_科研经费发票_金额" CHECK ("金额" > 0),
    CONSTRAINT "ck_科研经费发票_查重状态" CHECK ("查重状态" IN ('未查重','正常','疑似重复','已确认重复','已作废')),
    CONSTRAINT "ck_科研经费发票_OCR状态" CHECK ("OCR状态" IN ('未接入','人工录入','待接入','已识别'))
);
CREATE INDEX IF NOT EXISTS "ix_科研经费发票_项目" ON "科研经费发票" ("流程模板编号", "项目编号", "开票日期" DESC);
CREATE INDEX IF NOT EXISTS "ix_科研经费发票_号码" ON "科研经费发票" (lower(trim("发票号码")), "金额");
CREATE INDEX IF NOT EXISTS "ix_科研经费发票_供应商金额" ON "科研经费发票" (lower(trim("供应商名称")), "金额", "开票日期");

CREATE TABLE IF NOT EXISTS "项目经费预算调整申请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "申请原因" varchar(2000) NOT NULL,
    "原预算快照" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "申请预算" jsonb NOT NULL,
    "状态" varchar(20) NOT NULL DEFAULT '待审批',
    "申请人编号" integer NOT NULL,
    "审批人编号" integer,
    "审批意见" varchar(2000),
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "审批时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_项目经费预算调整_状态" CHECK ("状态" IN ('草稿','待审批','已批准','已驳回','已撤回')),
    CONSTRAINT "ck_项目经费预算调整_JSON" CHECK (jsonb_typeof("原预算快照") = 'array' AND jsonb_typeof("申请预算") = 'array')
);
CREATE INDEX IF NOT EXISTS "ix_项目经费预算调整_项目状态" ON "项目经费预算调整申请" ("流程模板编号", "项目编号", "状态", "申请时间" DESC);

CREATE TABLE IF NOT EXISTS "项目经费预算版本" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "版本号" integer NOT NULL,
    "来源申请编号" bigint REFERENCES "项目经费预算调整申请"("编号"),
    "版本状态" varchar(20) NOT NULL DEFAULT '现行',
    "预算快照" jsonb NOT NULL,
    "变更说明" varchar(2000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_项目经费预算版本" UNIQUE ("流程模板编号", "项目编号", "版本号"),
    CONSTRAINT "ck_项目经费预算版本_状态" CHECK ("版本状态" IN ('现行','历史','待审批')),
    CONSTRAINT "ck_项目经费预算版本_JSON" CHECK (jsonb_typeof("预算快照") = 'array')
);
CREATE INDEX IF NOT EXISTS "ix_项目经费预算版本_项目" ON "项目经费预算版本" ("流程模板编号", "项目编号", "版本号" DESC);

CREATE OR REPLACE FUNCTION "sp_项目经费预算调整_审批"(
    p_request_id bigint,
    p_approver_id integer,
    p_approve boolean,
    p_comment varchar DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
    v_request "项目经费预算调整申请"%ROWTYPE;
    v_version integer;
    v_old_snapshot jsonb;
    v_new_snapshot jsonb;
    v_row record;
BEGIN
    SELECT * INTO v_request FROM "项目经费预算调整申请" WHERE "编号"=p_request_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '预算调整申请不存在: %', p_request_id; END IF;
    IF v_request."状态" <> '待审批' THEN RAISE EXCEPTION '预算调整申请当前状态为 %，不能重复审批', v_request."状态"; END IF;
    IF NOT p_approve THEN
        UPDATE "项目经费预算调整申请"
           SET "状态"='已驳回',"审批人编号"=p_approver_id,"审批意见"=p_comment,"审批时间"=CURRENT_TIMESTAMP,"更新时间"=CURRENT_TIMESTAMP
         WHERE "编号"=p_request_id;
        RETURN jsonb_build_object('申请编号',p_request_id,'状态','已驳回');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        '编号',b."编号", '流程模板编号',b."流程模板编号", '项目编号',b."项目编号",
        '项目支出类型',b."项目支出类型", '项目支出内容',b."项目支出内容", '财务科目',b."财务科目",
        '批准经费',COALESCE(b."批准经费",0), '配套经费',COALESCE(b."配套经费",0), '编制依据',b."编制依据",
        '预算管理模式',b."预算管理模式", '到账编号',b."到账编号", '到账批次',b."到账批次"
    ) ORDER BY b."编号"),'[]'::jsonb) INTO v_old_snapshot
      FROM "项目经费预算" b
     WHERE b."流程模板编号"=v_request."流程模板编号" AND b."项目编号"=v_request."项目编号";
    SELECT COALESCE(MAX("版本号"),0)+1 INTO v_version FROM "项目经费预算版本"
     WHERE "流程模板编号"=v_request."流程模板编号" AND "项目编号"=v_request."项目编号";
    UPDATE "项目经费预算版本" SET "版本状态"='历史'
     WHERE "流程模板编号"=v_request."流程模板编号" AND "项目编号"=v_request."项目编号" AND "版本状态"='现行';
    INSERT INTO "项目经费预算版本" ("流程模板编号","项目编号","版本号","来源申请编号","版本状态","预算快照","变更说明","建立人编号")
    VALUES (v_request."流程模板编号",v_request."项目编号",v_version,v_request."编号",'现行',v_request."申请预算",p_comment,p_approver_id);
    DELETE FROM "项目经费预算" WHERE "流程模板编号"=v_request."流程模板编号" AND "项目编号"=v_request."项目编号";
    FOR v_row IN SELECT * FROM jsonb_to_recordset(v_request."申请预算") AS x(
        "项目支出类型" text, "项目支出内容" text, "财务科目" text, "批准经费" numeric,
        "配套经费" numeric, "编制依据" text, "预算管理模式" integer, "到账编号" integer, "到账批次" text
    ) LOOP
        IF COALESCE(length(trim(v_row."项目支出类型")),0)=0 OR COALESCE(length(trim(v_row."项目支出内容")),0)=0 OR COALESCE(length(trim(v_row."财务科目")),0)=0 THEN
            RAISE EXCEPTION '预算调整明细缺少支出类型、支出内容或财务科目';
        END IF;
        INSERT INTO "项目经费预算" ("流程模板编号","项目编号","项目支出类型","项目支出内容","财务科目","批准经费","配套经费","编制依据","预算管理模式","到账编号","到账批次")
        VALUES (v_request."流程模板编号",v_request."项目编号",trim(v_row."项目支出类型"),trim(v_row."项目支出内容"),trim(v_row."财务科目"),COALESCE(v_row."批准经费",0),COALESCE(v_row."配套经费",0),v_row."编制依据",COALESCE(v_row."预算管理模式",1),v_row."到账编号",v_row."到账批次");
    END LOOP;
    UPDATE "项目经费预算调整申请"
       SET "状态"='已批准',"审批人编号"=p_approver_id,"审批意见"=p_comment,"审批时间"=CURRENT_TIMESTAMP,"更新时间"=CURRENT_TIMESTAMP
     WHERE "编号"=p_request_id;
    v_new_snapshot := v_request."申请预算";
    RETURN jsonb_build_object('申请编号',p_request_id,'状态','已批准','版本号',v_version,'原预算快照',v_old_snapshot,'预算快照',v_new_snapshot);
END;
$$;

CREATE TABLE IF NOT EXISTS "项目经费年度结算" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "结算年度" integer NOT NULL,
    "状态" varchar(20) NOT NULL DEFAULT '开放',
    "批准预算" numeric(18,2) NOT NULL DEFAULT 0,
    "到账金额" numeric(18,2) NOT NULL DEFAULT 0,
    "支出金额" numeric(18,2) NOT NULL DEFAULT 0,
    "付款金额" numeric(18,2) NOT NULL DEFAULT 0,
    "结算说明" varchar(2000),
    "封账人编号" integer,
    "封账时间" timestamp without time zone,
    "重开人编号" integer,
    "重开时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_项目经费年度结算" UNIQUE ("流程模板编号", "项目编号", "结算年度"),
    CONSTRAINT "ck_项目经费年度结算_年度" CHECK ("结算年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_项目经费年度结算_状态" CHECK ("状态" IN ('开放','结算中','已封账','已重开')),
    CONSTRAINT "ck_项目经费年度结算_金额" CHECK ("批准预算" >= 0 AND "到账金额" >= 0 AND "支出金额" >= 0 AND "付款金额" >= 0)
);
CREATE INDEX IF NOT EXISTS "ix_项目经费年度结算_状态" ON "项目经费年度结算" ("状态", "结算年度");

CREATE OR REPLACE FUNCTION "tfn_科研经费发票查重"(
    p_flow_template_id integer,
    p_project_id integer,
    p_invoice_number varchar,
    p_supplier_name varchar,
    p_amount numeric,
    p_issue_date date,
    p_exclude_id bigint DEFAULT NULL
)
RETURNS TABLE (
    "编号" bigint,
    "流程模板编号" integer,
    "项目编号" integer,
    "发票号码" varchar,
    "开票日期" date,
    "金额" numeric,
    "供应商名称" varchar,
    "查重状态" varchar,
    "重复原因" text
)
LANGUAGE sql STABLE AS $$
SELECT i."编号", i."流程模板编号", i."项目编号", i."发票号码", i."开票日期", i."金额", i."供应商名称", i."查重状态",
       CASE
         WHEN lower(trim(i."发票号码")) = lower(trim(p_invoice_number)) THEN '发票号码相同'
         WHEN lower(trim(i."供应商名称")) = lower(trim(p_supplier_name))
              AND i."金额" = p_amount
              AND (p_issue_date IS NULL OR i."开票日期" = p_issue_date) THEN '供应商、金额和开票日期相同'
         ELSE '相似票据，请人工复核'
       END AS "重复原因"
  FROM "科研经费发票" i
 WHERE (p_exclude_id IS NULL OR i."编号" <> p_exclude_id)
   AND i."查重状态" <> '已作废'
   AND (
       lower(trim(i."发票号码")) = lower(trim(p_invoice_number))
       OR (lower(trim(i."供应商名称")) = lower(trim(p_supplier_name))
           AND i."金额" = p_amount
           AND (p_issue_date IS NULL OR i."开票日期" = p_issue_date))
   )
 ORDER BY i."编号" DESC;
$$;

CREATE OR REPLACE FUNCTION "fn_项目经费封账检查"()
RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_year integer;
    v_closed boolean;
BEGIN
    v_year := EXTRACT(YEAR FROM COALESCE(NEW."付款日期", NEW."交易日期", CURRENT_DATE));
    SELECT EXISTS (
        SELECT 1 FROM "项目经费年度结算" s
         WHERE s."流程模板编号" = NEW."流程模板编号"
           AND s."项目编号" = NEW."项目编号"
           AND s."结算年度" = v_year
           AND s."状态" = '已封账'
    ) INTO v_closed;
    IF v_closed THEN
        RAISE EXCEPTION '项目经费年度已封账，禁止新增或修改付款流水：流程模板=%，项目=%，年度=%',
            NEW."流程模板编号", NEW."项目编号", v_year USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trg_项目经费台账_封账约束" ON "项目经费台账";
CREATE TRIGGER "trg_项目经费台账_封账约束"
BEFORE INSERT OR UPDATE ON "项目经费台账"
FOR EACH ROW EXECUTE FUNCTION "fn_项目经费封账检查"();

CREATE OR REPLACE FUNCTION "fn_科研经费发票封账检查"()
RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_year integer;
BEGIN
    v_year := EXTRACT(YEAR FROM COALESCE(NEW."开票日期", CURRENT_DATE));
    IF EXISTS (
        SELECT 1 FROM "项目经费年度结算" s
         WHERE s."流程模板编号" = NEW."流程模板编号"
           AND s."项目编号" = NEW."项目编号"
           AND s."结算年度" = v_year
           AND s."状态" = '已封账'
    ) THEN
        RAISE EXCEPTION '项目经费年度已封账，禁止新增或修改发票：流程模板=%，项目=%，年度=%',
            NEW."流程模板编号", NEW."项目编号", v_year USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trg_科研经费发票_封账约束" ON "科研经费发票";
CREATE TRIGGER "trg_科研经费发票_封账约束"
BEFORE INSERT OR UPDATE ON "科研经费发票"
FOR EACH ROW EXECUTE FUNCTION "fn_科研经费发票封账检查"();

CREATE OR REPLACE FUNCTION "sp_项目经费年度结算"(
    p_flow_template_id integer,
    p_project_id integer,
    p_year integer,
    p_action varchar,
    p_operator_id integer,
    p_reason varchar DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
    v_row "项目经费年度结算"%ROWTYPE;
    v_budget numeric := 0;
    v_arrival numeric := 0;
    v_expense numeric := 0;
    v_paid numeric := 0;
BEGIN
    IF p_year < 2000 OR p_year > 2200 THEN RAISE EXCEPTION '结算年度无效'; END IF;
    SELECT COALESCE(SUM(COALESCE("批准经费",0) + COALESCE("配套经费",0)),0) INTO v_budget
      FROM "项目经费预算" WHERE "流程模板编号"=p_flow_template_id AND "项目编号"=p_project_id;
    SELECT COALESCE(SUM("到账金额"),0) INTO v_arrival
      FROM "项目经费到账" WHERE "流程模板编号"=p_flow_template_id AND "项目编号"=p_project_id AND EXTRACT(YEAR FROM "到账日期")=p_year;
    SELECT COALESCE(SUM("报销金额"),0) INTO v_expense
      FROM "报销" WHERE "流程模板编号"=p_flow_template_id AND "项目编号"=p_project_id AND EXTRACT(YEAR FROM "报销时间")=p_year;
    SELECT COALESCE(SUM("金额"),0) INTO v_paid
      FROM "项目经费台账" WHERE "流程模板编号"=p_flow_template_id AND "项目编号"=p_project_id
        AND "业务类型"='实际付款' AND "状态"='已付款' AND EXTRACT(YEAR FROM COALESCE("付款日期","交易日期"))=p_year;

    INSERT INTO "项目经费年度结算" ("流程模板编号","项目编号","结算年度","状态","批准预算","到账金额","支出金额","付款金额","结算说明","封账人编号","封账时间","重开人编号","重开时间")
    VALUES (p_flow_template_id,p_project_id,p_year,CASE WHEN p_action='close' THEN '已封账' ELSE '已重开' END,v_budget,v_arrival,v_expense,v_paid,p_reason,
            CASE WHEN p_action='close' THEN p_operator_id ELSE NULL END,CASE WHEN p_action='close' THEN CURRENT_TIMESTAMP ELSE NULL END,
            CASE WHEN p_action='reopen' THEN p_operator_id ELSE NULL END,CASE WHEN p_action='reopen' THEN CURRENT_TIMESTAMP ELSE NULL END)
    ON CONFLICT ("流程模板编号","项目编号","结算年度") DO UPDATE SET
      "状态" = CASE WHEN p_action='close' THEN '已封账' ELSE '已重开' END,
      "批准预算"=EXCLUDED."批准预算","到账金额"=EXCLUDED."到账金额","支出金额"=EXCLUDED."支出金额","付款金额"=EXCLUDED."付款金额",
      "结算说明"=EXCLUDED."结算说明","封账人编号"=CASE WHEN p_action='close' THEN p_operator_id ELSE "项目经费年度结算"."封账人编号" END,
      "封账时间"=CASE WHEN p_action='close' THEN CURRENT_TIMESTAMP ELSE "项目经费年度结算"."封账时间" END,
      "重开人编号"=CASE WHEN p_action='reopen' THEN p_operator_id ELSE "项目经费年度结算"."重开人编号" END,
      "重开时间"=CASE WHEN p_action='reopen' THEN CURRENT_TIMESTAMP ELSE "项目经费年度结算"."重开时间" END,
      "更新时间"=CURRENT_TIMESTAMP
    RETURNING * INTO v_row;
    RETURN jsonb_build_object('编号',v_row."编号",'流程模板编号',v_row."流程模板编号",'项目编号',v_row."项目编号",'结算年度',v_row."结算年度",'状态',v_row."状态",'批准预算',v_row."批准预算",'到账金额',v_row."到账金额",'支出金额',v_row."支出金额",'付款金额',v_row."付款金额");
END;
$$;

UPDATE "系统迁移版本"
   SET "版本" = 78,
       "脚本" = '078_finance_controls.sql',
       "检查摘要" = '增加发票人工查重、预算调整版本、年度结算封账及付款回写约束',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
